const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]).buffer(50000); // 50km buffer around San Jose

  // Time periods
  const june2020 = ee.DateRange('2020-06-01', '2020-06-30');
  const august2020 = ee.DateRange('2020-08-20', '2020-09-02'); // Window around Aug 26

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  let juneCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(sanJose)
    .filterDate(june2020)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let augustCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(sanJose)
    .filterDate(august2020)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  // Check collection sizes
  const juneSize = juneCol.size().getInfo();
  const augustSize = augustCol.size().getInfo();

  console.log(`June 2020 Images: ${juneSize}, August 2020 Images: ${augustSize}`);

  if (juneSize === 0 || augustSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get median composites and calculate NBR
  function calculateNBR(image) {
    // Apply scaling factors
    const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
    const nir = opticalBands.select('SR_B5');
    const swir = opticalBands.select('SR_B7');

    const nbr = nir.subtract(swir).divide(nir.add(swir)).rename('NBR');
    return image.addBands(nbr);
  }

  const juneMedian = calculateNBR(juneCol.median());
  const augustMedian = calculateNBR(augustCol.median());

  // 4. Burn scar detection - NBR < 0.1 indicates burn scars
  const burnThreshold = 0.1;
  const juneBurned = juneMedian.select('NBR').lt(burnThreshold);
  const augustBurned = augustMedian.select('NBR').lt(burnThreshold);

  // Count burned pixels
  const juneCount = juneBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sanJose,
    scale: 1000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const augustCount = augustBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sanJose,
    scale: 1000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`June burned pixels: ${Math.round(juneCount)}`);
  console.log(`August burned pixels: ${Math.round(augustCount)}`);

  // Validation checks
  if (juneCount === 0 || augustCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (juneCount === null || augustCount === null || 
      isNaN(juneCount) || isNaN(augustCount) ||
      juneCount < 0 || augustCount < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final comparison - did burn scars expand?
  const expansion = ((augustCount - juneCount) / juneCount) * 100;
  console.log(`Burn scar expansion: ${expansion.toFixed(1)}%`);

  // Consider expansion if >10% increase
  if (expansion > 10) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
